'use strict';
const originalRender=render;let planBusy=false,lastPlan=null,obsStatus=null,lastComfyId='',planBrief='';
async function api(url,body){const r=await fetch(url,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const data=await r.json();if(!r.ok)throw Error(data.error||'请求失败');return data;}
render=function(){if(page!=='真实集成'){originalRender();document.getElementById('nav').innerHTML+='<button data-page="真实集成">真实集成</button>';const n=app.querySelector('.notice');if(n)n.textContent='舞台设备仍为模拟。真实集成页面提供本地 AI 导演草案、obs-websocket-js 协议联调和 ComfyUI 接口；模拟结果不代表实体设备性能。';return;}
document.getElementById('nav').innerHTML=['演出控制','节目编排','素材与预演','设备与故障','执行报告','组件接入','真实集成'].map(x=>`<button data-page="${x}" class="${page===x?'active':''}">${x}</button>`).join('');app.innerHTML=`<div class="eyebrow">演出自动化 / 软件集成</div><h1>真实 AI 与组件联调</h1><div class="notice">本地模型执行真实推理；OBS 当前默认连接协议模拟器，不是 OBS Studio。灯光、调音与实体舞台设备未接入。视频是否真实生成，以 ComfyUI 任务结果为准。</div><div class="grid"><section><div class="card"><h2>AI 导演草案</h2><form id="ai-plan"><label><span>节目说明</span><textarea name="brief" rows="4" maxlength="2000" required placeholder="例如：五分钟国风音乐会开场，从安静星空转为热烈主唱，再以谢幕收束。">${esc(planBrief)}</textarea></label><button ${planBusy?'disabled':''}>${planBusy?'本地模型推理中…':'生成真实 AI 草案'}</button></form>${lastPlan?`<pre>${esc(lastPlan.text)}</pre><p class="muted">模型 ${esc(lastPlan.model)} · ${(lastPlan.elapsedMs/1000).toFixed(1)} 秒 · ${lastPlan.cues.length} 条 cue</p><button data-real="import-plan">追加到节目并重新排练</button>`:''}</div><div class="card"><h2>ComfyUI 接口</h2><p class="muted">支持 API 格式工作流提交和任务回查。当前未安装视频模型，不会把占位内容标成视频。</p><button data-real="comfy-status">检查 ComfyUI</button><pre id="comfy-status">未检查</pre><form id="comfy-submit"><label><span>API 格式工作流 JSON</span><textarea name="workflow" rows="5" required placeholder="粘贴从 ComfyUI 导出的 API 工作流"></textarea></label><button>提交真实生成任务</button></form><p class="muted">任务编号：${esc(lastComfyId||'尚未提交')}</p><button data-real="comfy-history" ${lastComfyId?'':'disabled'}>查询任务结果</button><pre id="comfy-history"></pre></div></section><section><div class="card"><h2>OBS 协议联调</h2><p class="muted">真实复用 obs-websocket-js，执行 WebSocket 握手、请求和场景切换回读。默认由本项目的协议模拟器响应。</p><button data-real="obs-status">连接并读取场景</button>${obsStatus?`<p>模式：<b>${esc(obsStatus.mode)}</b> · 当前场景 ${esc(obsStatus.currentProgramSceneName)}</p><div class="row">${obsStatus.scenes.map(x=>`<button class="secondary" data-scene="${esc(x.sceneName)}">${esc(x.sceneName)}</button>`).join('')}</div>`:''}<pre id="obs-result">${obsStatus?esc(JSON.stringify(obsStatus.version,null,2)):'尚未连接'}</pre><button data-real="cue-obs" ${state.status==='运行中'?'':'disabled'}>将下一条 cue 的机位发送并回读</button><p class="muted">只验证机位动作，不推进整个 cue，也不将灯光、调音标记为已执行。</p></div><div class="card"><h2>AI 服务状态</h2><button data-real="ai-status">检查真实集成状态</button><pre id="integration-status">未检查</pre></div></section></div>`;};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||(!b.dataset.real&&!b.dataset.scene))return;e.stopImmediatePropagation();b.disabled=true;try{if(b.dataset.scene){const r=await api('/api/obs/scene',{sceneName:b.dataset.scene});obsStatus=await api('/api/obs/status');state.logs.unshift({at:new Date().toISOString(),message:`OBS ${r.mode} 场景回读：${r.currentProgramSceneName}`});persist();render();toast('场景切换回读成功');return;}switch(b.dataset.real){case 'ai-status':document.getElementById('integration-status').textContent=JSON.stringify(await api('/api/integrations'),null,2);break;case 'obs-status':obsStatus=await api('/api/obs/status');render();break;case 'comfy-status':document.getElementById('comfy-status').textContent=JSON.stringify(await api('/api/comfy/status'),null,2);break;case 'comfy-history':document.getElementById('comfy-history').textContent=JSON.stringify(await api('/api/comfy/history/'+lastComfyId),null,2);break;case 'import-plan':if(!lastPlan||['运行中','故障暂停','人工接管'].includes(state.status))throw Error('请先结束当前场次');for(const cue of lastPlan.cues)Show.edit(state,cue);persist();lastPlan=null;page='节目编排';render();toast('AI 草案已追加，请人工检查后重新排练');break;case 'cue-obs':{if(state.status!=='运行中')throw Error('请先开始模拟演出');const cue=state.cues[state.cursor];const r=await api('/api/obs/scene',{sceneName:cue.camera});state.logs.unshift({at:new Date().toISOString(),message:`cue ${cue.name} 机位回读成功（${r.mode}），其他设备未执行`});persist();document.getElementById('obs-result').textContent=JSON.stringify(r,null,2);break;}}}catch(err){toast(err.message)}finally{b.disabled=false;}},true);
document.addEventListener('submit',async e=>{if(!['ai-plan','comfy-submit'].includes(e.target.id))return;e.preventDefault();e.stopImmediatePropagation();const data=new FormData(e.target);try{if(e.target.id==='ai-plan'){if(planBusy)return;planBusy=true;lastPlan=null;const brief=data.get('brief');planBrief=brief;render();lastPlan=await api('/api/ai/plan',{brief});render();}else{const r=await api('/api/comfy/prompt',{workflow:JSON.parse(data.get('workflow'))});lastComfyId=r.prompt_id;render();toast('任务已入队，生成尚未完成');}}catch(err){toast(err.message)}finally{planBusy=false;if(page==='真实集成')render();}},true);
render();
